#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
size_t flatten(const value*v,size_t n,int*out){size_t k=0;for(size_t i=0;i<n;i++){if(v[i].kind==INTEGER)out[k++]=v[i].integer;else if(v[i].kind==ARRAY)k+=flatten(v[i].items,v[i].count,out+k);}return k;}
